// Pure body validation · no HTTP
const body = $input.first().json.body || $input.first().json;

const ALLOWED_FUNCTIONS = new Set([
    'facebook_ads_library_scraper',
    'instagram_scraper',
    'instagram_post_comments_scraper',
    'linkedin_company_scraper',
    'tiktok_profile_scraper',
    'google_ads_scraper',
    'tiktok_creative_center_scraper',
    'youtube_channel_scraper',
    'youtube_video_scraper',
    'youtube_comments_scraper',
    'google_serp_scraper',
    'google_maps_scraper',
    'similarweb_scraper',
    'trustpilot_scraper',
    'software_review_scraper',
    'twitter_scraper',
    // 17ª (2026-09-06) · LEER EL SITIO DEL CLIENTE. Medido: ninguna de las 16
    // leía una web · la única con pinta (similarweb) devuelve tráfico, no contenido.
    'website_content_scraper',
    // OBJETIVOS NUEVOS (2026-09-07) · no son brazos nuevos: reusan el brazo del mapa
    // y el del sitio. Lo que agregan es DE QUIÉN es lo raspado — hoy el Servicio no
    // lo puede decir, y por eso la ficha propia quedaría archivada como si fuera de
    // un competidor (medido: la corrida del 06-sep quedó como google_maps_competitive).
    'own_google_maps_profile',
    'competitor_website_scraper',
    // FACEBOOK (2026-09-09) · el ÚNICO de los cuatro datos que faltaban que pedía brazo
    // nuevo: entre los 17 no había raspador de PÁGINA, sólo de biblioteca de anuncios.
    // Entra dentro del objetivo «las cinco redes».
    'facebook_page_scraper',
    // FUENTES PÚBLICAS (ronda 71) · reseñas de las plataformas que aplican al rubro y textos/videos de las redes del cliente
    'resenas_google_maps',
    'resenas_tripadvisor',
    'resenas_booking',
    'resenas_facebook',
    'resenas_app_store',
    'publicaciones_facebook',
    'videos_instagram',
    'videos_tiktok',
    'videos_youtube',
    // MENCIONES DE TERCEROS (14-oct) · publicaciones de OTRAS cuentas que etiquetan al negocio
    'menciones_en_redes',
  ]);
// TERCER DESTINO (2026-09-10 · Lenovo) · ADITIVO · los dos de siempre no se tocan.
// 'respuesta' = devolver lo encontrado a quien preguntó, y nada más: no escribe en
// el cerebro y no llama a nadie de vuelta. Ya funcionaba todo el camino de abajo
// (should_brain y should_callback dan false, y `guardado_en` ya dice «sólo la
// respuesta»): lo único que faltaba era que esta lista lo dejara pasar.
// 🔴 Y NO se hace punto de recepción propio: obligaría a pausar y retomar, y esa
// maquinaria sirve verdes falsos.
const ALLOWED_DESTINATIONS = new Set(['brain_rag', 'callback_url', 'both', 'respuesta']);

const errors = [];
if (!body.client_id || typeof body.client_id !== 'string') errors.push('client_id required');
if (!body.apify_function || !ALLOWED_FUNCTIONS.has(body.apify_function)) errors.push('apify_function invalid');
if (!body.destination || !ALLOWED_DESTINATIONS.has(body.destination)) errors.push('destination invalid');
if ((body.destination === 'callback_url' || body.destination === 'both') && !body.callback_url) errors.push('callback_url required for destination=callback_url|both');
// PIEZA 4 (2026-09-05) · el ensayo se DECIDE, no se hereda. Sin esto, un flujo nuevo
// copia a un vecino, se trae el `dry_run: true` clavado y 'funciona' sin traer un dato.
if (typeof body.dry_run !== 'boolean') errors.push('dry_run required · true o false explícito · no se asume');
// PLAN v3 · V8 (15-oct) · ADITIVO y opcional: ausente = comportamiento de hoy
if (body.origen !== undefined && body.origen !== null && !/^[a-z][a-z0-9_]{0,31}$/.test(String(body.origen))) errors.push('origen invalid · texto corto en minúsculas (a-z, 0-9, _)');
if (body.workflow_execution_id !== undefined && body.workflow_execution_id !== null && (typeof body.workflow_execution_id !== 'string' || body.workflow_execution_id.length > 64)) errors.push('workflow_execution_id invalid · texto de hasta 64 caracteres');
if (body.tope_usd !== undefined && body.tope_usd !== null && !(typeof body.tope_usd === 'number' && body.tope_usd > 0 && body.tope_usd <= 5)) errors.push('tope_usd invalid · número mayor que 0 y hasta 5');

return [{
  json: {
    validation_ok: errors.length === 0,
    validation_errors: errors,
    body,
    dry_run: body.dry_run === true,
  },
}];

// Modo ensayo canonical · synthetic response per apify_function shape
const ctx = $input.first().json;
const synthetic = {
  facebook_ads_library_scraper: [{ pageName: 'Synthetic Competitor', adActiveStatus: 'active', adBody: 'Synthetic ad body canon', adCreatedTime: '2026-05-25T00:00:00Z' }],
  instagram_scraper: [{ username: 'synthetic_handle', followers: 12345, posts: 100, biography: 'Synthetic IG bio' }],
  instagram_post_comments_scraper: [{ handle: 'synthetic_handle', postUrl: 'https://www.instagram.com/p/synth', comment: 'Synthetic comment canon' }],
  linkedin_company_scraper: [{ companyName: 'Synthetic Co', followers: 5000, employees: 50, posts: [{ text: 'Synthetic LinkedIn post' }] }],
  tiktok_profile_scraper: [{ username: 'synthetic_handle', followers: 8000, posts: [{ description: 'Synthetic TikTok post' }] }],
};

return [{
  json: {
    ...ctx,
    apify_data: synthetic[ctx.apify_function] || [],
    apify_run_id: 'dry-run-' + Date.now(),
    cost_estimate_usd: 0,
    duration_ms: 0,
    dry_run: true,
  },
}];

const NL = String.fromCharCode(10);
const validateCtx = $('Validate Body').first().json;
const body = validateCtx.body || {};
const scrapeOutput = $input.first().json;

const apifyFunction = body.apify_function;
const clientId = body.client_id;
const destination = body.destination;
const dryRun = validateCtx.dry_run;

// ARREGLO 2026-09-05 · esto leía SÓLO el primer elemento y esperaba un arreglo
// adentro. El raspador devuelve UNA FILA POR REGISTRO: el primer elemento ES un
// registro, así que ninguna rama coincidía y `data` quedaba vacío. Medido por la
// puerta: Maps devolvió la ficha completa e Instagram el perfil completo, y las
// dos veces se escribió "(no data returned…)" en el cerebro del cliente.
const items = $input.all().map((i) => i.json).filter(Boolean);
const primero = items[0] || {};
let data = [];
if (Array.isArray(primero.apify_data)) data = primero.apify_data;        // ensayo y formas viejas
else if (Array.isArray(primero.body)) data = primero.body;               // forma vieja
else if (Array.isArray(scrapeOutput)) data = scrapeOutput;               // por si alguna vez llega así
else data = items;                                                        // el caso REAL · una fila por registro
// los marcadores de error del propio raspador NO son datos
// (ej. TikTok devuelve {code:0, msg:'Please enter valid cookies…'})
// CLASIFICAR EL CERO (2026-09-05) · «no existe» y «no pude ver» NO son lo mismo.
// El flujo del plan va a leer esto: la diferencia entre «este competidor no pauta»
// y «no pudimos mirar si pauta» cambia el plan que se escribe. Si se leen igual,
// el plan afirma cosas que nadie midió.
const crudos = data.length;
data = data.filter((r) => r && typeof r === 'object' && !r.error && !(r.code === 0 && r.msg));
// lo que se cayó en el filtro eran avisos del raspador, no datos
const descartados = crudos - data.length;
const motivosDeCeguera = [];
for (const r of (items || [])) {
  if (r && r.error) motivosDeCeguera.push(String(r.error).slice(0, 120));
  else if (r && r.code === 0 && r.msg) motivosDeCeguera.push(String(r.msg).slice(0, 120));
  else if (r && r.errorDescription) motivosDeCeguera.push(String(r.errorDescription).slice(0, 120));
}


// FUENTES PÚBLICAS (ronda 71) · reseñas, textos y videos de las plataformas del cliente · una línea por pieza, SIN datos personales de quien opinó.
const ES_FUENTE_PUBLICA = /^(resenas_|publicaciones_|videos_|menciones_)/.test(apifyFunction);
const primeroTexto = (o, ks) => { for (const k of ks) { const v = o && o[k]; if (typeof v === 'string' && v.trim()) return v.trim(); } return ''; };
const aplanar = (v) => String(v == null ? '' : v).replace(/\s+/g, ' ').trim();
// ronda 75 · salida REAL de YouTube: «subtitles» es una lista de {srt}; se deja solo lo que se dice (sin números ni tiempos ni líneas repetidas)
const subtitulosComoTexto = (v) => {
  if (typeof v === 'string') return v.trim();
  if (!Array.isArray(v)) return '';
  const partes = [];
  for (const s of v) {
    const crudo = typeof s === 'string' ? s : (s && (s.srt || s.text || s.vtt)) || '';
    for (const l of String(crudo).split(NL)) {
      const t = l.trim();
      if (!t || /^[0-9]+$/.test(t) || t.indexOf('-->') >= 0) continue;
      if (partes[partes.length - 1] !== t) partes.push(t);
    }
  }
  return partes.join(' ');
};
const MIN_PALABRAS_DE_VOZ = 4;
const ONOMATOPEYA = /^(b+a*m+|ba+m*|bu+m+|bi+|bu+|la+|na+|da+|do+|doo+|oh+|ah+|eh+|uh+|mm+|hm+|yeah|ye+|ha+|hey|oo+|woo+|sh+|pam|rum|cha+)$/;
function esVozReal(texto) {
  const crudo = typeof texto === 'string' ? texto : '';
  const limpio = crudo.replace(/\[[^\]]{0,40}\]|\([^)]{0,40}\)|[♪♫♬]/g, ' ');
  if (/\[(music|musica|música|applause|aplausos|noise|ruido)\]/i.test(crudo) && limpio.replace(/[^\p{L}]/gu, '').length < 20) return { voz: false, motivo: 'solo etiqueta de música o ruido' };
  const palabras = (limpio.toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').match(/[a-zñü]+/g) || []);
  if (palabras.length < MIN_PALABRAS_DE_VOZ) return { voz: false, motivo: 'muy corta (' + palabras.length + ' palabras)' };
  const onomatopeyas = palabras.filter(function (p) { return ONOMATOPEYA.test(p); }).length;
  if (onomatopeyas / palabras.length > 0.4) return { voz: false, motivo: 'mayormente sílabas u onomatopeyas' };
  const distintas = new Set(palabras).size;
  if (distintas / palabras.length < 0.4) return { voz: false, motivo: 'casi una sola palabra repetida' };
  return { voz: true, motivo: 'texto de voz' };
}

function lineasDeFuente(fn, items) {
  const out = [];
  const meter = (it) => {
    if (!it || typeof it !== 'object') return;
    if (fn.indexOf('resenas_') === 0) {
      // la tienda de apps trae las reseñas ANIDADAS en la ficha de la app
      if (Array.isArray(it.reviews) && it.reviews.length && !it.text) { for (const r of it.reviews) meter(r); return; }
      const bien = primeroTexto(it, ['liked']); const mal = primeroTexto(it, ['disliked']);
      const texto = primeroTexto(it, ['text', 'reviewText', 'review', 'comment', 'body', 'content']) || [bien && 'lo que gustó: ' + bien, mal && 'lo que no: ' + mal].filter(Boolean).join(' · ');
      const titulo = primeroTexto(it, ['title', 'reviewTitle']);
      if (!texto && !titulo) return;
      const estrellas = it.stars != null ? it.stars : (it.rating != null ? it.rating : (it.score != null ? it.score : (it.ratingValue != null ? it.ratingValue : null)));
      const fecha = String(primeroTexto(it, ['publishedAtDate', 'publishedDate', 'reviewDate', 'date', 'createdAt', 'time', 'updatedAt'])).slice(0, 10);
      const recomienda = it.isRecommended === true ? 'recomienda' : (it.isRecommended === false ? 'no recomienda' : '');
      const resp = primeroTexto(it, ['responseFromOwnerText', 'ownerResponse']);
      out.push([estrellas != null ? '★' + estrellas : '', recomienda, fecha].filter(Boolean).join(' · ') + (titulo && texto ? ' · ' + aplanar(titulo) : '') + ' · «' + aplanar(texto || titulo) + '»' + (resp ? ' [respuesta del negocio: «' + aplanar(resp).slice(0, 300) + '»]' : ''));
    } else if (fn === 'menciones_en_redes') {
      // publicación de OTRA cuenta que etiqueta o menciona al negocio: fecha · pie · dirección; SIN el nombre de quien la publicó (dato de un tercero)
      const pie = primeroTexto(it, ['caption', 'text']);
      if (!pie) return;
      const dir = primeroTexto(it, ['url']);
      out.push('mención · ' + String(primeroTexto(it, ['timestamp', 'takenAtTimestamp', 'date'])).slice(0, 10) + ' · «' + aplanar(pie) + '»' + (dir ? ' · ' + dir : ''));
    } else if (fn === 'publicaciones_facebook') {
      const texto = primeroTexto(it, ['text', 'message', 'caption', 'postText']); const trans = primeroTexto(it, ['videoTranscript', 'transcript', 'captionText', 'ocrText']);
      if (!texto && !trans) return;
      out.push([String(primeroTexto(it, ['time', 'date', 'timestamp', 'createdAt'])).slice(0, 10)].filter(Boolean).join(' · ') + (texto ? ' · «' + aplanar(texto) + '»' : '') + (trans ? ' · lo que se dice en el video: «' + aplanar(trans) + '»' : ''));
    } else {
      const caption = primeroTexto(it, ['caption', 'text', 'description', 'title']);
      const transCruda = primeroTexto(it, ['transcript', 'transcription', 'videoTranscript', 'subtitle']) || subtitulosComoTexto(it.subtitles);
      const voz = transCruda ? esVozReal(transCruda) : null;
      const trans = voz && voz.voz ? transCruda : '';
      const url = primeroTexto(it, ['url', 'videoUrl', 'postUrl', 'webVideoUrl', 'inputUrl']);
      if (!caption && !transCruda) return;
      out.push('video' + (url ? ' ' + url : '') + ' · ' + String(primeroTexto(it, ['timestamp', 'createTimeISO', 'date', 'uploadDate', 'publishedAt'])).slice(0, 10) + (caption ? ' · pie: «' + aplanar(caption) + '»' : '') + ' · ' + (trans ? 'lo que se dice: «' + aplanar(trans) + '»' : (transCruda ? 'SIN voz (' + voz.motivo + ')' : (it.transcripcion_error ? 'SIN transcripción (no se pudo leer: ' + it.transcripcion_error + ')' : (it.transcripcion_leida ? 'SIN voz (Apify transcribió el video y no encontró voz)' : 'SIN transcripción')))));
    }
  };
  for (const it of items) meter(it);
  return out;
}
function seccionesDeFuente(fn, items, etiqueta) {
  const lineas = lineasDeFuente(fn, items);
  const secciones = []; let actual = ''; let usadas = 0;
  const TOPE = 7000; const MAX_SECCIONES = 8;
  for (const l of lineas) {
    if ((actual + NL + l).length > TOPE) { if (actual) secciones.push(actual); actual = l.slice(0, TOPE); } else { actual = actual ? actual + NL + l : l; }
    usadas++;
  }
  if (actual) secciones.push(actual);
  const recortada = secciones.length > MAX_SECCIONES;
  const finales = secciones.slice(0, MAX_SECCIONES);
  return { lineas: lineas.length, recortada, secciones: finales.map((t, i) => ({ section_label: etiqueta + (finales.length > 1 ? ' · ' + (i + 1) + '/' + finales.length : ''), text: t + (recortada && i === finales.length - 1 ? NL + '⟨recortado · se guardaron ' + MAX_SECCIONES + ' secciones de ' + secciones.length + '⟩' : '') })) };
}

const sectionLabelBase = {
  facebook_ads_library_scraper: 'meta_ads_competitive',
  instagram_scraper: 'instagram_competitive',
  instagram_post_comments_scraper: 'instagram_voc',
  linkedin_company_scraper: 'linkedin_competitive',
  tiktok_profile_scraper: 'tiktok_competitive',
  google_ads_scraper: 'google_ads_competitive',
  tiktok_creative_center_scraper: 'tiktok_creative_trends',
  youtube_channel_scraper: 'youtube_channel_competitive',
  youtube_video_scraper: 'youtube_video_competitive',
  youtube_comments_scraper: 'youtube_voc',
  google_serp_scraper: 'google_serp_seo',
  website_content_scraper: 'sitio_del_cliente',
  // OBJETIVOS NUEVOS (2026-09-07) · el rótulo dice de quién es. Si dijera
  // «competitive» para la ficha propia, el agente del plan leería al cliente como
  // si fuera su competencia.
  own_google_maps_profile: 'ficha_propia_maps',
  competitor_website_scraper: 'sitio_del_competidor',
  facebook_page_scraper: 'facebook_page',
  google_maps_scraper: 'google_maps_competitive',
  similarweb_scraper: 'similarweb_traffic',
  trustpilot_scraper: 'trustpilot_reputation',
  software_review_scraper: 'software_reviews_competitive',
  twitter_scraper: 'twitter_competitive',
  ...({"resenas_google_maps":"resenas_google_maps_propias","resenas_tripadvisor":"resenas_tripadvisor_propias","resenas_booking":"resenas_booking_propias","resenas_facebook":"resenas_facebook_propias","resenas_app_store":"resenas_app_store_propias","publicaciones_facebook":"facebook_publicaciones_propias","videos_instagram":"instagram_videos_propios","videos_tiktok":"tiktok_videos_propios","videos_youtube":"youtube_videos_propios"}),
}[apifyFunction] || 'apify_scrape';
// relevo 51 · el rótulo dice de quién es: SOLO cuando quien llama declara que el objetivo es PROPIO (metadata.target_kind === 'own').
// Sin esa marca (corrida diaria, planeación…) nada cambia. La bio propia ya no se archiva como «competidor».
const rotuloPropio = { instagram_scraper: 'instagram_propio', facebook_page_scraper: 'facebook_page_propia', linkedin_company_scraper: 'linkedin_propio', tiktok_profile_scraper: 'tiktok_propio', youtube_channel_scraper: 'youtube_channel_propio', twitter_scraper: 'twitter_propio' };
const esPropio = !!(body && body.metadata && body.metadata.target_kind === 'own');
const sectionLabel = (esPropio && rotuloPropio[apifyFunction]) ? rotuloPropio[apifyFunction] : sectionLabelBase;

const sourceTable = {
  facebook_ads_library_scraper: 'client_competitive_landscape',
  instagram_scraper: 'client_competitive_landscape',
  instagram_post_comments_scraper: 'client_voc_library',
  linkedin_company_scraper: 'client_competitive_landscape',
  tiktok_profile_scraper: 'client_competitive_landscape',
  google_ads_scraper: 'client_competitive_landscape',
  tiktok_creative_center_scraper: 'client_competitive_landscape',
  youtube_channel_scraper: 'client_competitive_landscape',
  youtube_video_scraper: 'client_competitive_landscape',
  youtube_comments_scraper: 'client_voc_library',
  google_serp_scraper: 'client_competitive_landscape',
  website_content_scraper: 'client_web_pages',
  competitor_website_scraper: 'client_web_pages',
  facebook_page_scraper: 'client_competitive_landscape',
  ...Object.fromEntries(['resenas_google_maps', 'resenas_tripadvisor', 'resenas_booking', 'resenas_facebook', 'resenas_app_store', 'publicaciones_facebook', 'videos_instagram', 'videos_tiktok', 'videos_youtube', 'menciones_en_redes'].map((f) => [f, 'client_voc_library'])),
}[apifyFunction] || 'client_competitive_landscape';

// 🔴 ARREGLO 2026-09-05 · antes, cuando no había datos, se FABRICABA un cartel
// y se ingestaba al cerebro como si fuera evidencia. Un cartel que dice "no hay
// nada" no es conocimiento del cliente: es basura con forma de dato, y el flujo
// del plan lo va a leer. Ahora, sin datos → CERO secciones y motivo declarado.
const sinDatos = data.length === 0;
const FUENTE = ES_FUENTE_PUBLICA && !sinDatos ? seccionesDeFuente(apifyFunction, data, sectionLabelBase) : null;
const text = (sinDatos || FUENTE)
  ? (FUENTE ? FUENTE.secciones.map((s) => s.text).join(NL + NL) : '')
  : data.slice(0, 50).map((item, i) => {
      const lines = ['## Record ' + (i + 1)];
      // LA TEMPORADA (2026-09-06) · las horas concurridas YA vienen en la ficha de
      // Maps y se estaban tirando: el volcado recorta cada campo a 400 caracteres y
      // el bloque mide 4.286. Se resume a una línea por día — que es lo que un plan
      // necesita — y se declara cuando el negocio no las publica.
      if (item && item.popularTimesHistogram && typeof item.popularTimesHistogram === 'object') {
        const dias = Object.keys(item.popularTimesHistogram);
        if (dias.length) {
          const resumen = dias.map((d) => {
            const tramos = (item.popularTimesHistogram[d] || []).filter((h) => h && typeof h.occupancyPercent === "number");
            if (!tramos.length) return d + ': sin datos';
            const pico = tramos.reduce((a, b) => (b.occupancyPercent > a.occupancyPercent ? b : a));
            const abiertos = tramos.filter((h) => h.occupancyPercent > 0);
            const media = Math.round(tramos.reduce((s, h) => s + h.occupancyPercent, 0) / tramos.length);
            return d + ': pico ' + pico.hour + 'h (' + pico.occupancyPercent + '%) · media ' + media + '%' +
              (abiertos.length ? ' · con gente de ' + abiertos[0].hour + 'h a ' + abiertos[abiertos.length - 1].hour + 'h' : '');
          });
          lines.push('- **afluencia por día**: ' + resumen.join(' | '));
        } else {
          lines.push('- **afluencia por día**: el negocio no la publica en su ficha');
        }
      }
      // 🔴 EL RECORTE DE 400, QUE MUTILABA EN SILENCIO (2026-09-06)
      // Medido sobre muestras reales de 5 raspadores: 14 de 57 campos estructurados
      // (25%) salían cortados, 140.990 caracteres perdidos, y NADIE se enteraba.
      // No era el caso del menú: la lista de servicios de Náufrago (545) se cortaba a
      // mitad de palabra, y la lista de competidores que da Google (499) también.
      // Ahora: reparto por presupuesto, del más chico al más grande — lo chico entra
      // ENTERO y lo enorme se lleva lo que sobra — y TODO recorte se declara.
      const CUPO_MINIMO = 400;          // nunca peor que antes
      const PRESUPUESTO = 5200;         // por registro · deja aire bajo el tope de 8.000
      const estructurados = [];
      for (const [k, v] of Object.entries(item && typeof item === 'object' ? item : {})) {
        if (v === null || v === undefined) continue;
        if (k === 'popularTimesHistogram') continue;                 // ya resumido arriba
        if (typeof v === 'object') estructurados.push([k, JSON.stringify(v)]);
      }
      const cupo = new Map();
      {
        const orden = estructurados.slice().sort((a, b) => a[1].length - b[1].length);
        let queda = PRESUPUESTO;
        let faltan = orden.length;
        for (const [k, s] of orden) {
          const parte = Math.max(CUPO_MINIMO, Math.floor(queda / Math.max(faltan, 1)));
          const uso = Math.min(s.length, parte);
          cupo.set(k, uso);
          queda -= uso;
          faltan--;
        }
      }
      if (item && typeof item === 'object') {
        for (const [k, v] of Object.entries(item)) {
          if (v === null || v === undefined) continue;
          if (typeof v === 'string' || typeof v === 'number' || typeof v === 'boolean') {
            lines.push('- **' + k + '**: ' + v);
          } else if (typeof v === 'object') {
            if (k === 'popularTimesHistogram') continue;              // ya resumido arriba
            const s = JSON.stringify(v);
            const uso = cupo.has(k) ? cupo.get(k) : CUPO_MINIMO;
            // se recorta SÓLO si no entra · y cuando se recorta, SE DICE
            lines.push('- **' + k + '**: ' + (s.length <= uso
              ? s
