  for (var i = 0; i < listas.length; i++) {
    var l = Array.isArray(listas[i]) ? listas[i] : []
    for (var j = 0; j < l.length; j++) {
      var u = urlDeImagen(l[j] && (l[j].original_image_url || l[j].resized_image_url || l[j].video_preview_image_url))
