function huellaCorta(t) { var h = 5381; for (var i = 0; i < t.length; i++) h = ((h << 5) + h + t.charCodeAt(i)) >>> 0; return h.toString(36) }
function fotosDeOtrasFuentes(funcion, items, opciones) {
  var tope = (opciones && opciones.max) || 12
