  var lista = Array.isArray(items) ? items : []
  var out = []
  var vistos = {}
  var agrega = function (f) { if (out.length < tope && f.src && !vistos[f.owner_role + '|' + f.handle + '|' + f.post_id]) { vistos[f.owner_role + '|' + f.handle + '|' + f.post_id] = 1; out.push(f) } }
  for (var i = 0; i < lista.length; i++) {
    var it = lista[i]
    if (!it || typeof it !== 'object') continue
    if (funcion === 'google_maps_scraper') {
      var u = urlDeImagen(it.imageUrl)
      var id = String(it.placeId || it.cid || '').toLowerCase().replace(/[^a-z0-9_-]/g, '').slice(0, 60)
      var nombre = limpiar(it.title, 80)
      if (!u || !(id || nombre)) continue
      agrega({ owner_role: 'competidor', handle: slugDeFuente(nombre, 40) || 'mapas', post_id: 'maps-' + (id || slugDeFuente(nombre, 40)), tipo: 'maps_portada', src: u, caption: limpiar(nombre + (it.categoryName ? ' · ' + it.categoryName : '') + (it.address ? ' · ' + it.address : ''), 300) || null, post_url: urlDeImagen(it.url), medio: 'imagen', posicion: 'unica' })
      // 31-oct · «guardar todo»: TODAS las fotos que trae la ficha (`imageUrls`, si la llamada pidió `maxImages`), no solo la portada
      var extras = Array.isArray(it.imageUrls) ? it.imageUrls : []
      for (var k = 0; k < extras.length; k++) {
        var xu = urlDeImagen(typeof extras[k] === 'string' ? extras[k] : extras[k] && extras[k].imageUrl)
        if (!xu || xu === u) continue
        agrega({ owner_role: 'competidor', handle: slugDeFuente(nombre, 40) || 'mapas', post_id: 'maps-' + (id || slugDeFuente(nombre, 40)) + '-f' + (k + 1), tipo: 'maps_foto', src: xu, caption: limpiar(nombre, 300) || null, post_url: urlDeImagen(it.url), medio: 'imagen', posicion: 'hijo-' + (k + 1) })
      }
    } else if (funcion === 'competitor_website_scraper') {
      var host = hostDe(it.url), og = ogImagenDe(it)
      if (!host || !og || vistos['web|' + host]) continue
      vistos['web|' + host] = 1
      agrega({ owner_role: 'competidor', handle: host, post_id: 'web-' + slugDeFuente(host, 30) + '-' + huellaCorta(og), tipo: 'web_portada', src: og, caption: limpiar(it.metadata && it.metadata.title, 300) || null, post_url: urlDeImagen(it.url), medio: 'imagen', posicion: 'unica' })
    } else if (funcion === 'facebook_ads_library_scraper') {
      var sn = it.snapshot || {}
      var img = imagenDeAnuncio(sn)
      var aid = String(it.ad_archive_id || it.adArchiveID || '').replace(/[^0-9a-z]/gi, '')
      if (!img || !aid) continue
      var pagina = slugDeFuente(sn.page_name || it.page_name || '', 40) || 'anuncio'
      var cuerpo = sn.body && (sn.body.text || sn.body)
      agrega({ owner_role: 'referencia', handle: pagina, post_id: 'ad-' + aid, tipo: 'anuncio', src: img, caption: limpiar(typeof cuerpo === 'string' ? cuerpo : sn.title, 300) || null, post_url: urlDeImagen(sn.link_url), medio: 'imagen', posicion: 'unica' })
    }
  }
  return out
}

// ───────────────────────────── fotos y capturas de los SITIOS WEB (31-oct · «guardar todo») ─────────────────────────────
/**
 * De cada página de un sitio (propio o de un competidor) salen TODAS sus imágenes (etiquetas <img>/<source>, og:image, imágenes del markdown) y una CAPTURA de pantalla de las páginas principales.
 * 🔴 «nunca una ajena como propia»: el ROL de las imágenes sale del rol de la PÁGINA (la base lo decide con la regla única «¿es del cliente?»); una página de referencia/tercero NO deja imágenes.
 *    Dentro de una página propia, una imagen servida desde otro dominio (anuncio, socio, píxel) se rotula 'referencia', nunca 'propio'.
 * Pura: sin red ni `URL`. Solo JPG/PNG/WebP (el resto no pasa «Fotos · revisar»): se descartan aquí y se cuentan.
 */
var SEGUNDOS_NIVELES = ['com', 'co', 'org', 'net', 'edu', 'gob', 'gov', 'ac']
function baseDeHost(h) {
  var p = String(h || '').toLowerCase().split('.')
  if (p.length <= 2) return p.join('.')
  var penultimo = p[p.length - 2]
  return SEGUNDOS_NIVELES.indexOf(penultimo) !== -1 && p[p.length - 1].length === 2 ? p.slice(-3).join('.') : p.slice(-2).join('.')
}
/** resuelve una dirección (absoluta, //, /ruta o relativa) contra la página; sin `URL` */
function resolverContra(base, ruta) {
  var r = String(ruta || '').trim().replace(/&amp;/g, '&')
  if (!r || r.indexOf('data:') === 0 || r.indexOf('blob:') === 0 || r.indexOf('javascript:') === 0) return null
  if (/^https?:\/\//i.test(r)) return r
  var m = /^(https?:\/\/[^\/?#]+)([^?#]*)/i.exec(String(base || ''))
  if (!m) return null
  if (r.indexOf('//') === 0) return (/^https/i.test(base) ? 'https:' : 'http:') + r
  if (r.charAt(0) === '/') return m[1] + r
  var dir = m[2].replace(/[^\/]*$/, '')
  return m[1] + (dir || '/') + r
}
var RUIDO_DE_IMAGEN = /(?:\/favicon|favicon\.|apple-touch-icon|\/sprite|spacer|1x1|pixel|\/tr\?|facebook\.com\/tr|doubleclick|googletagmanager|google-analytics|gravatar|emoji|\/wp-includes\/)/i
function esFormatoPermitido(u) {
  var limpia = String(u).split('#')[0].split('?')[0].toLowerCase()
  if (/\.(svg|gif|avif|ico|bmp|tiff?|mp4|webm|pdf)$/.test(limpia)) return false
  return true
}
function imagenesDeHtml(html, markdown) {
  var out = []
  var h = String(html || '')
  var re = /<(img|source)\b[^>]*>/gi
  var m
  while ((m = re.exec(h)) !== null) {
    var tag = m[0]
    var alt = /\balt=["']([^"']*)["']/i.exec(tag)
    var attrs = ['src', 'data-src', 'data-lazy-src', 'data-original', 'srcset', 'data-srcset']
    for (var i = 0; i < attrs.length; i++) {
      var v = new RegExp('\\b' + attrs[i] + '=["\']([^"\']+)["\']', 'i').exec(tag)
      if (!v) continue
      if (/srcset$/i.test(attrs[i])) {
        // la más grande de la lista: «url 480w, url 1200w» → la de mayor ancho
        var mejor = null, mejorW = -1
        v[1].split(',').forEach(function (c) { var t = c.trim().split(/\s+/); var w = parseInt(t[1], 10) || 0; if (t[0] && w >= mejorW) { mejor = t[0]; mejorW = w } })
        if (mejor) out.push({ src: mejor, alt: alt ? alt[1] : '' })
      } else out.push({ src: v[1], alt: alt ? alt[1] : '' })
      break
    }
  }
  var md = String(markdown || '')
  var rm = /!\[([^\]]*)\]\(([^)\s]+)/g
  while ((m = rm.exec(md)) !== null) out.push({ src: m[2], alt: m[1] })
  return out
}
function metaImagenes(item) {
  var out = []
  var og = item && item.metadata && item.metadata.openGraph
  if (Array.isArray(og)) for (var i = 0; i < og.length; i++) { var p = og[i] && og[i].property; if ((p === 'og:image' || p === 'og:image:url' || p === 'og:image:secure_url' || p === 'twitter:image') && og[i].content) out.push({ src: og[i].content, alt: '' }) }
  return out
}
/**
 * `opciones`: { rol: 'propio' | 'competidor' (el de la página; otro valor ⇒ []), tope (imágenes por llamada, 80), capturas (páginas con captura, 8) }
 * Devuelve filas de `client_social_images` (sin client_id): { owner_role, handle, post_id, tipo, src, caption, post_url, medio, posicion }.
 */
function fotosDeSitio(items, opciones) {
  var rol = opciones && opciones.rol
  if (rol !== 'propio' && rol !== 'competidor') return []
  var tope = (opciones && opciones.tope) || 80
  var topeCapturas = (opciones && opciones.capturas) || 8
  var lista = Array.isArray(items) ? items : []
  var out = []
  var vistos = {}
  var capturas = 0
  var descartadas = { formato: 0, ruido: 0 }
  for (var i = 0; i < lista.length; i++) {
    var it = lista[i]
    if (!it || typeof it !== 'object' || !it.url) continue
    var host = hostDe(it.url)
    if (!host) continue
    var titulo = limpiar(it.metadata && it.metadata.title, 200)
    if (it.screenshotUrl && capturas < topeCapturas && urlDeImagen(it.screenshotUrl)) {
      capturas++
      out.push({ owner_role: rol, handle: host, post_id: 'captura-' + slugDeFuente(host, 30) + '-' + huellaCorta(String(it.url)), tipo: 'web_captura', src: it.screenshotUrl, caption: limpiar('Captura de pantalla · ' + (titulo || it.url), 300), post_url: urlDeImagen(it.url), medio: 'imagen', posicion: 'portada' })
    }
    var candidatas = metaImagenes(it).concat(imagenesDeHtml(it.html, it.markdown))
    for (var j = 0; j < candidatas.length; j++) {
      if (out.length >= tope + capturas) break
      var src = resolverContra(it.url, candidatas[j].src)
      if (!src || !urlDeImagen(src)) continue
      if (RUIDO_DE_IMAGEN.test(src)) { descartadas.ruido++; continue }
      if (!esFormatoPermitido(src)) { descartadas.formato++; continue }
      var clave = src.split('#')[0]
      if (vistos[clave]) continue
      vistos[clave] = 1
      // el rol de la IMAGEN: en una página propia, solo lo servido desde el dominio del sitio es propio; lo demás es referencia
      var rolImagen = rol === 'propio' && baseDeHost(hostDe(src)) !== baseDeHost(host) ? 'referencia' : rol
      out.push({ owner_role: rolImagen, handle: host, post_id: 'web-' + slugDeFuente(host, 30) + '-' + huellaCorta(clave), tipo: 'web_imagen', src: src, caption: limpiar(candidatas[j].alt || titulo, 300) || null, post_url: urlDeImagen(it.url), medio: 'imagen', posicion: 'unica' })
    }
  }
  out.descartadas = descartadas
  return out
}


// COPIA DE FOTOS · 3/5 · REVISAR · CC#1 · 2026-09-29 · 03-oct: SIN DUPLICADOS (huella SHA-256 · la portada de un carrusel es su hijo 1: se queda UNA y la repetida se DECLARA, no se sube) y el contexto de cada foto viaja a la tabla.
// (la lógica `sha256Hex` viene de fotos-contexto-logica.js, pegada arriba por el constructor) Mira lo que bajó CADA foto: si no es una imagen entera, se DECLARA aquí
// (fila estado=no_bajo con la causa exacta) y no pasa a subirse. Pasan solo las buenas, con su huella para verificar la subida.
const SB = 'https://ordaeyxvvvdqsznsecjx.supabase.co'
const auth = { apikey: $env.SUPABASE_SERVICE_ROLE_KEY, Authorization: 'Bearer ' + $env.SUPABASE_SERVICE_ROLE_KEY }
const metas = $('Fotos · lista').all().map((i) => i.json)
const entradas = $input.all()
const host = (u) => String(u).split('/')[2] || 'host desconocido'
const buenas = []
const fallas = []
const duplicadas = []
const vistas = {}
// 27-oct · el MISMO archivo es una sola foto en todo el cliente (no solo dentro de un post): lo de competencia o referencia que ya está guardado con otro rol/cuenta no se vuelve a subir
// (medido en df7e47cc: 11 «competidor» eran las propias). La propia siempre entra. Si la lectura falla, se sigue sin esta guarda (la lectura y el etiquetado también deduplican por huella).
const previosPorHuella = {}
if (metas[0] && metas[0].client_id) {
  const previos = await this.helpers.httpRequest({ url: SB + '/rest/v1/client_social_images?client_id=eq.' + metas[0].client_id + '&hash_archivo=not.is.null&select=hash_archivo,owner_role,handle,post_id&limit=1000', method: 'GET', json: true, timeout: 15000, headers: auth }).catch(() => [])
  for (const p of Array.isArray(previos) ? previos : []) if (p.hash_archivo && !previosPorHuella[p.hash_archivo]) previosPorHuella[p.hash_archivo] = p
}
// el contexto que acompaña a cada fila (lo trae `Fotos · lista`)
const contexto = (m) => ({ caption: m.caption || null, posted_at: m.posted_at || null, post_url: m.post_url || null, posicion: m.posicion || null, medio: m.medio || null })
for (let i = 0; i < metas.length; i++) {
  const m = metas[i]
  const e = entradas[i]
  let causa = null
  let buf = null
  let ct = null
  if (!e) causa = 'sin respuesta del paso de descarga'
  else if (e.json && e.json.error) causa = 'red · ' + String(e.json.error.message || e.json.error).slice(0, 110)
  else if (e.json && e.json.statusCode && e.json.statusCode !== 200) causa = 'HTTP ' + e.json.statusCode
  else if (!e.binary || !e.binary.data) causa = 'la respuesta no trajo archivo'
  else {
    buf = await this.helpers.getBinaryDataBuffer(i, 'data')
    const h = buf.slice(0, 4).toString('hex')
    ct = h.startsWith('ffd8ff') ? 'image/jpeg' : h === '89504e47' ? 'image/png' : h === '52494646' && buf.slice(8, 12).toString('ascii') === 'WEBP' ? 'image/webp' : null
    if (!ct) causa = 'no es una imagen (empieza con ' + h + ' · ' + String(e.binary.data.mimeType || 'sin tipo') + ')'
    else if (buf.length > 10 * 1024 * 1024) causa = 'demasiado grande · ' + buf.length + ' B'
  }
  if (causa) {
    fallas.push({ client_id: m.client_id, owner_role: m.owner_role, handle: m.handle, post_id: m.post_id, tipo: m.tipo, url: null, estado: 'no_bajo', causa: causa + ' · ' + host(m.src), ...contexto(m) })
    continue
  }
  // 🔴 la MISMA imagen dos veces dentro de un post (portada = hijo 1) no se sube dos veces: se queda la primera y la repetida se declara
  const hash = sha256Hex(buf)
  const claveDup = String(m.post_id).replace(/-c\d+$/, '') + '|' + hash
  if (vistas[claveDup] !== undefined) { duplicadas.push({ post_id: m.post_id, igual_a: vistas[claveDup], hash }); continue }
  const previo = previosPorHuella[hash]
  if (previo && m.owner_role !== 'propio' && !(previo.owner_role === m.owner_role && previo.handle === m.handle && previo.post_id === m.post_id)) { duplicadas.push({ post_id: m.post_id, igual_a: previo.owner_role + ':' + previo.handle + '/' + previo.post_id, hash }); continue }
  vistas[claveDup] = m.post_id
  if (!previosPorHuella[hash]) previosPorHuella[hash] = { owner_role: m.owner_role, handle: m.handle, post_id: m.post_id }
  const ext = ct === 'image/png' ? 'png' : ct === 'image/webp' ? 'webp' : 'jpg'
  buenas.push({
    json: { ...m, ct, hash_archivo: hash, bytes: buf.length, magic: buf.slice(0, 4).toString('hex'), path: m.client_id + '/' + m.owner_role + '/' + m.handle + '/' + m.post_id + '.' + ext },
    binary: { data: e.binary.data },
  })
}
// las que no bajaron se DECLARAN ya en la tabla (aunque nada más suba)
if (fallas.length) {
  const w = await this.helpers.httpRequest({
    url: SB + '/rest/v1/client_social_images?on_conflict=client_id,owner_role,handle,post_id', method: 'POST', json: true,
    returnFullResponse: true, ignoreHttpStatusErrors: true, timeout: 20000, body: fallas,
    headers: { ...auth, 'Content-Type': 'application/json', Prefer: 'resolution=merge-duplicates,return=minimal' },
  })
  if (w.statusCode >= 300) throw new Error('COPIA_FOTOS_SIN_ANOTAR · la tabla respondió HTTP ' + w.statusCode + ' · ' + JSON.stringify(w.body).slice(0, 200))
}
const resumen = (fs) => fs.length + ' de ' + metas.length + ' · ' + fs.slice(0, 5).map((f) => f.handle + '/' + f.post_id + ' → ' + f.causa).join(' | ')
if (!buenas.length) {
  if (fallas.length) throw new Error('FOTOS_NO_BAJARON · ' + resumen(fallas))
  return []
}
buenas.forEach((b) => { b.json._fallas = fallas; b.json._total = metas.length; b.json._duplicadas = duplicadas })
return buenas

